declare(strict_types=1);require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../_helper.php';uks_require_access($pdo);if(!uks_can_manage($pdo))deny_access();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$st=$pdo->prepare('SELECT * FROM uks_obat WHERE id=? LIMIT 1');$st->execute([$id]);$row=$st->fetch();if(!$row)exit('Obat tidak ditemukan.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$kode=trim((string)$_POST['kode']);$nama=trim((string)$_POST['nama']);$satuan=trim((string)$_POST['satuan']);$min=max(0,(int)$_POST['stok_minimum']);$lokasi=trim((string)$_POST['lokasi']);$kadaluarsa=trim((string)($_POST['tanggal_kadaluarsa']??''));if($kadaluarsa!=='' && !preg_match('/^\d{4}-\d{2}-\d{2}$/',$kadaluarsa))$kadaluarsa='';$aktif=(int)($_POST['aktif']??1);try{$st=$pdo->prepare('UPDATE uks_obat SET kode=?,nama=?,satuan=?,stok_minimum=?,lokasi=?,tanggal_kadaluarsa=?,aktif=? WHERE id=?');$st->execute([$kode,$nama,$satuan,$min,$lokasi,$kadaluarsa!==''?$kadaluarsa:null,$aktif,$id]);uks_audit($pdo,'UPDATE',$id,'Memperbarui master obat UKS');uks_flash('Master obat berhasil diperbarui.');redirect('uks/obat/index.php');}catch(Throwable $e){$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Kode obat sudah digunakan.':'Gagal memperbarui obat.';}}$page_title='Edit Obat UKS';require_once __DIR__.'/../../layouts/header.php';require_once __DIR__.'/../../layouts/sidebar.php';?><main class="main uks-module-page"><header class="topbar"><div class="topbar-title">Edit Obat</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Edit Obat UKS</h1><p>Stok saat ini: <strong><?=number_format((int)$row['stok_saat_ini'])?></strong>. Perubahan stok dilakukan melalui kartu stok.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Kembali</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-card"><div class="form-grid"><div class="form-group"><label>Kode *</label><input class="form-control" name="kode" value="<?=e($row['kode'])?>" required></div><div class="form-group"><label>Nama Obat *</label><input class="form-control" name="nama" value="<?=e($row['nama'])?>" required></div><div class="form-group"><label>Satuan *</label><input class="form-control" name="satuan" value="<?=e($row['satuan'])?>" required></div><div class="form-group"><label>Stok Minimum</label><input class="form-control" type="number" min="0" name="stok_minimum" value="<?=e($row['stok_minimum'])?>"></div><div class="form-group"><label>Lokasi</label><input class="form-control" name="lokasi" value="<?=e($row['lokasi']??'')?>"></div><div class="form-group"><label>Tanggal Kedaluwarsa</label><input class="form-control" type="date" name="tanggal_kadaluarsa" value="<?=e($row['tanggal_kadaluarsa']??'')?>"><small class="text-muted">Perbarui jika stok yang tersedia memiliki tanggal kedaluwarsa berbeda.</small></div><div class="form-group"><label>Status</label><select class="form-control" name="aktif"><option value="1" <?=$row['aktif']?'selected':''?>>Aktif</option><option value="0" <?=!$row['aktif']?'selected':''?>>Nonaktif</option></select></div></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Batal</a></div></form></section></main><?php require_once __DIR__.'/../../layouts/footer.php';
